@inject IJSRuntime JS

<div class="message-list" @ref="_scrollContainer">
    @if (IsLoading)
    {
        <div class="loading-indicator">Loading older messages...</div>
    }
    @foreach (var message in Messages)
    {
        <MessageBubble Message="message"
                       ThreadReplyCount="GetThreadReplyCount(message.Id)"
                       OnOpenThread="OnOpenThread"
                       OnReact="OnReact" />
    }
    <div @ref="_bottomAnchor"></div>
</div>

@code {
    [Parameter, EditorRequired]
    public List<Message> Messages { get; set; } = [];

    [Parameter]
    public Dictionary<int, ThreadSummary> ThreadSummaries { get; set; } = [];

    [Parameter]
    public bool IsLoading { get; set; }

    [Parameter]
    public bool HasMoreMessages { get; set; }

    [Parameter]
    public EventCallback<int> OnOpenThread { get; set; }

    [Parameter]
    public EventCallback<(int MessageId, string Emoji)> OnReact { get; set; }

    [Parameter]
    public EventCallback OnLoadMore { get; set; }

    private ElementReference _scrollContainer;
    private ElementReference _bottomAnchor;
    private DotNetObjectReference<MessageList>? _selfRef;
    private IJSObjectReference? _jsModule;
    private bool _shouldScrollToBottom = true;
    private int _previousMessageCount;

    private int GetThreadReplyCount(int messageId) =>
        ThreadSummaries.TryGetValue(messageId, out var summary) ? summary.ReplyCount : 0;

    protected override async Task OnAfterRenderAsync(bool firstRender)
    {
        if (firstRender)
        {
            _selfRef = DotNetObjectReference.Create(this);
            _jsModule = await JS.InvokeAsync<IJSObjectReference>("import",
                "./_content/sv-f18f142e1c0b4d7bbefe95a9eda6af67/Components/Pages/Chat/MessageList.razor.js");
            await _jsModule.InvokeVoidAsync("initScrollHandler", _scrollContainer, _selfRef);
        }

        if (_shouldScrollToBottom && Messages.Count > _previousMessageCount)
        {
            if (_jsModule is not null)
            {
                await _jsModule.InvokeVoidAsync("scrollToBottom", _scrollContainer);
            }
        }
        _previousMessageCount = Messages.Count;
    }

    [JSInvokable]
    public async Task OnScrolledToTop()
    {
        if (HasMoreMessages && !IsLoading)
        {
            _shouldScrollToBottom = false;
            await OnLoadMore.InvokeAsync();
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (_jsModule is not null)
        {
            try
            {
                await _jsModule.InvokeVoidAsync("dispose", _scrollContainer);
                await _jsModule.DisposeAsync();
            }
            catch (JSDisconnectedException) { }
        }
        _selfRef?.Dispose();
    }
}

.message-list {
    flex: 1;
    overflow-y: auto;
    padding: 8px 0;
    display: flex;
    flex-direction: column;
}

.loading-indicator {
    text-align: center;
    padding: 10px;
    color: #888;
    font-size: 0.85rem;
}

const scrollHandlers = new WeakMap();

export function initScrollHandler(element, dotNetRef) {
    if (!element) return;
    const handler = () => {
        if (element.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    };
    element.addEventListener('scroll', handler);
    scrollHandlers.set(element, handler);
    // Start scrolled to bottom
    element.scrollTop = element.scrollHeight;
}

export function scrollToBottom(element) {
    if (!element) return;
    element.scrollTop = element.scrollHeight;
}

export function dispose(element) {
    if (!element) return;
    const handler = scrollHandlers.get(element);
    if (handler) {
        element.removeEventListener('scroll', handler);
        scrollHandlers.delete(element);
    }
}

.message-input-area {
    display: flex;
    gap: 8px;
    padding: 12px 16px;
    border-top: 1px solid #e0e0e0;
    background-color: #fff;
    align-items: flex-end;
}

.message-textarea {
    flex: 1;
    border: 1px solid #ccc;
    border-radius: 8px;
    padding: 8px 12px;
    font-size: 0.9rem;
    resize: none;
    font-family: inherit;
    outline: none;
    transition: border-color 0.15s;
}

.message-textarea:focus {
    border-color: #1264a3;
}

.send-btn {
    background-color: #1264a3;
    color: #fff;
    border: none;
    border-radius: 8px;
    padding: 8px 20px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
    white-space: nowrap;
}

.send-btn:hover:not(:disabled) {
    background-color: #0d5289;
}

.send-btn:disabled {
    opacity: 0.5;
    cursor: not-allowed;
}

