toolArgs.file_text:
const scrollHandlers = new WeakMap();

export function initScrollHandler(element, dotNetRef) {
    if (!element) return;
    const handler = () => {
        if (element.scrollTop === 0) {
            dotNetRef.invokeMethodAsync('OnScrolledToTop');
        }
    };
    element.addEventListener('scroll', handler);
    scrollHandlers.set(element, handler);
    // Start scrolled to bottom
    element.scrollTop = element.scrollHeight;
}

export function scrollToBottom(element) {
    if (!element) return;
    element.scrollTop = element.scrollHeight;
}

export function dispose(element) {
    if (!element) return;
    const handler = scrollHandlers.get(element);
    if (handler) {
        element.removeEventListener('scroll', handler);
        scrollHandlers.delete(element);
    }
}

