.message-area {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #fff;
    overflow: hidden;
}

.area-header {
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.area-header h4 {
    margin: 0;
    font-size: 1.1rem;
    font-weight: 700;
    color: #1a1a2e;
}

.area-description {
    font-size: 0.82rem;
    color: #888;
}

.thread-panel {
    display: flex;
    flex-direction: column;
    height: 100%;
    background-color: #fff;
    border-left: 1px solid #e0e0e0;
    overflow: hidden;
}

.thread-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 16px;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.thread-header h5 {
    margin: 0;
    font-size: 1rem;
    font-weight: 700;
}

.close-btn {
    background: none;
    border: none;
    font-size: 1.1rem;
    cursor: pointer;
    color: #666;
    padding: 2px 6px;
    border-radius: 4px;
}

.close-btn:hover {
    background-color: #f0f0f0;
    color: #333;
}

.thread-root-message {
    padding: 12px 16px;
    background-color: #f8f9fa;
    border-bottom: 1px solid #e0e0e0;
    flex-shrink: 0;
}

.root-author {
    font-weight: 700;
    font-size: 0.9rem;
    color: #1a1a2e;
}

.root-content {
    margin: 4px 0 0;
    font-size: 0.88rem;
    color: #444;
    line-height: 1.4;
}

.thread-divider {
    padding: 8px 16px;
    font-size: 0.78rem;
    color: #888;
    border-bottom: 1px solid #eee;
    flex-shrink: 0;
}

.thread-replies {
