arguments.file_text:
@page "/chat"
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="chat-sidebar">
        <ChannelSidebar Channels="_channels"
                        ActiveChannelId="_activeChannelId"
                        OnChannelSelected="HandleChannelSelected" />
    </div>

    <div class="chat-main @(_threadOpen ? "with-thread" : "")">
        @if (_activeChannel is not null)
        {
            <MessageArea ChannelName="@_activeChannel.Name"
                         ChannelDescription="@_activeChannel.Description"
                         Messages="_messages"
                         ThreadSummaries="_threadSummaries"
                         IsLoading="_loadingMessages"
                         HasMoreMessages="_hasMoreMessages"
                         OnOpenThread="HandleOpenThread"
                         OnReact="HandleReact"
                         OnLoadMore="HandleLoadMore"
                         OnSendMessage="HandleSendMessage" />
        }
        else
        {
            <div class="no-channel-selected">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (_threadOpen && _threadRootMessage is not null)
    {
        <div class="chat-thread">
            <ThreadPanel RootMessage="_threadRootMessage"
                         ThreadMessages="_threadMessages"
                         OnClose="HandleCloseThread"
                         OnReplySend="HandleThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> _channels = [];
    private int _activeChannelId;
    private Channel? _activeChannel;
    private List<Message> _messages = [];
    private Dictionary<int, ThreadSummary> _threadSummaries = [];
    private bool _loadingMessages;
    private bool _hasMoreMessages = true;

    private bool _threadOpen;
    private Message? _threadRootMessage;
    private List<Message> _threadMessages = [];

    protected override async Task OnInitializedAsync()
    {
        _channels = await ChatService.GetChannelsAsync();
        if (_channels.Count > 0)
        {
            await HandleChannelSelected(_channels[0].Id);
        }
    }

    private async Task HandleChannelSelected(int channelId)
    {
        if (_activeChannelId == channelId) return;

        _activeChannelId = channelId;
        _activeChannel = _channels.FirstOrDefault(c => c.Id == channelId);
        _messages = [];
        _threadSummaries = [];
        _hasMoreMessages = true;
        _threadOpen = false;

        await LoadMessages(skip: 0);
        await ChatService.MarkChannelReadAsync(channelId);

        // Update the local unread count
        var idx = _channels.FindIndex(c => c.Id == channelId);
        if (idx >= 0)
        {
            var ch = _channels[idx];
            _channels[idx] = ch with { UnreadCount = 0 };
        }
    }

    private async Task LoadMessages(int skip)
    {
        _loadingMessages = true;
        StateHasChanged();

        var batch = await ChatService.GetMessagesAsync(_activeChannelId, skip, PageSize);
        if (batch.Count < PageSize)
        {
            _hasMoreMessages = false;
        }

        if (skip == 0)
        {
            _messages = batch;
        }
        else
        {
            // Prepend older messages
            _messages = [..batch, .._messages];
        }

        BuildThreadSummaries();
        _loadingMessages = false;
    }

    private void BuildThreadSummaries()
    {
        // Build thread summaries from messages that are replies
        var replies = _messages.Where(m => m.ReplyToId is not null).ToList();
        var summaries = new Dictionary<int, ThreadSummary>();
        foreach (var reply in replies)
        {
            var rootId = reply.ReplyToId!.Value;
            if (summaries.TryGetValue(rootId, out var existing))
            {
                summaries[rootId] = existing with
                {
                    ReplyCount = existing.ReplyCount + 1,
                    LastReplyAt = reply.SentAt > existing.LastReplyAt ? reply.SentAt : existing.LastReplyAt
                };
            }
