+            else
+            {
+                summaries[rootId] = new ThreadSummary(rootId, 1, reply.SentAt);
+            }
+        }
+        _threadSummaries = summaries;
+    }
+
+    private async Task HandleLoadMore()
+    {
+        if (!_hasMoreMessages || _loadingMessages) return;
+        await LoadMessages(skip: _messages.Count);
